// C ABI of shout, a bada-compatible v1 IME engine (docs/bada-compatible-v1.md; generated by
// export! in src/lib.rs). JSON in, JSON out. Returned strings belong to the engine and stay valid
// until the next call on the same engine. A new IME: rename shout_ and Shout to its prefix, and add
// the optional functions it exports (bada ime's engine/include/bada.h has them all).
#ifndef SHOUT_H
#define SHOUT_H

#include <stddef.h>
#include <stdint.h>

typedef struct ShoutData ShoutData;      // no data: pass NULL
typedef struct ShoutEngine ShoutEngine;

// Required.
ShoutEngine *shout_new(const ShoutData *data);
void shout_free(ShoutEngine *engine);
const char *shout_key(ShoutEngine *engine, const char *event_json);
const char *shout_set_mode(ShoutEngine *engine, uint32_t mode);   // 0 muhenkan, else henkan
const char *shout_flush(ShoutEngine *engine);

// Optional, exported by shout.
const char *shout_set_settings(ShoutEngine *engine, const char *settings_json);  // → settings in effect
const char *shout_host_selection(ShoutEngine *engine, const char *text);
const char *shout_catalog(ShoutEngine *engine);
const char *shout_state(ShoutEngine *engine);  // read-only: what's staged, mode, menu (§12)

#endif
